"""role_axes.py — tassonomie ad assi per i ruoli, misurate sul TESTO reale del manuale.

PERCHE': la categoria «Taunter» conteneva solo build sull'asse A (svantaggio), che e' la
versione debole del ruolo: 120 sottoclassi toccavano il controllo, 10 lo facevano davvero.
Lo stesso difetto — una categoria popolata con la sola meccanica piu' ovvia — e' probabile
negli altri ruoli. Qui ogni ruolo ha i SUOI assi e una REGOLA DI AMMISSIONE, cosi' la
categoria contiene chi copre il ruolo, non chi lo sfiora.

Fonti scandite (tre contenitori, non uno: un rilevatore che ne legge due su tre classifica
male un terzo delle build): privilegi di sottoclasse risolti, talenti, incantesimi.

Output: data/role-axes.json
"""
from __future__ import annotations

import json
import re
from pathlib import Path

SITE = Path(r"C:\Users\Fabrizio\workspace\public-site")
DATA = SITE / "data"
OUT = DATA / "role-axes.json"

RUOLI: dict[str, dict] = {
    "healer": {
        "nome": "Guaritore",
        "assi": {
            "H1 cura diretta": ["regain hit points", "restore hit points", "heals", "healing",
                                "regains", "hit points equal"],
            # 'prevent' da solo matcha testo di sapore: un ladro risultava «Guaritore» per H2.
            "H2 prevenzione": ["temporary hit points", "resistance to", "reduce the damage",
                               "halves the damage"],
            "H3 rianimazione": ["revivify", "raise dead", "resurrection", "return to life",
                                "back from the dead", "resurrect", "dying"],
            "H4 condizioni": ["remove", "ends the condition", "no longer", "cured", "cure",
                              "removes one level of exhaustion", "ends one"],
            # 'bonus action' da solo matcha OGNI classe (Cunning Action, Second Wind, ...):
            # serve il verbo di cura accanto all'economia.
            "H5 economia": ["bonus action to restore", "bonus action to heal",
                            "as a bonus action, you can restore", "as a bonus action, you can heal",
                            "as a reaction when", "without using an action"],
        },
        # La versione DEBOLE e' la cura grezza (H1) da sola: costa l'azione e arriva dopo il
        # danno. Un guaritore vero previene, rianima o toglie condizioni.
        "ammissione": ["*due_di_H1H2H3H4H5"],
        "regola": "almeno un asse fra prevenzione (H2), rianimazione (H3) o rimozione di condizioni (H4): la cura grezza da sola e' la versione debole",
    },
    "summoner": {
        "nome": "Evocatore",
        "assi": {
            "S1 evocazione": ["summon", "conjure", "you summon", "appears in an unoccupied",
                              "animate dead", "create undead", "familiar"],
            "S2 comando": ["no action required", "command it", "you command", "obeys your",
                           "takes its turn", "you can use a bonus action to command"],
            "S3 potenziamento": ["the summon", "your summon", "its attacks", "adds your",
                                 "increases by", "gains temporary hit points"],
            "S4 quantita": ["each of your", "number of", "two creatures", "multiple", "swarm",
                            "as many as"],
            "S5 persistenza": ["until dispelled", "24 hours", "permanently", "reassert",
                               "lasts until", "no concentration"],
        },
        # Evocare senza poter COMANDARE (S2) significa spendere azioni ogni turno: la versione
        # debole. Serve comando, potenziamento o persistenza.
        "ammissione": ["S2", "S3", "S5"],
        "regola": "evocazione (S1) piu' almeno un asse fra comando (S2), potenziamento (S3) o persistenza (S5): un summon che costa l'azione ogni turno e' la versione debole",
    },
    "dps": {
        "nome": "Danno",
        "assi": {
            "D1 singolo": ["one creature", "a creature you can see", "target", "single",
                           "against that creature"],
            "D2 area": ["each creature", "in a", "sphere", "cone", "line", "radius", "cube"],
            "D3 critico": ["critical", "crit", "score a critical hit", "critical range",
                           "19-20", "18-20"],
            "D4 ripetibile": ["at will", "each of your turns", "on each of your turns",
                              "whenever you", "no action required", "you can use"],
            "D5 esplosivo": ["extra damage", "additional damage", "per level", "increases by",
                             "extra 1d", "extra 2d", "double"],
            "D6 multiattacco": ["attack twice", "extra attack", "two attacks", "three attacks",
                                "number of attacks"],
        },
        # Un DPS che sa fare SOLO danno singolo e' la versione stretta: non regge contro gruppi
        # ne' scala. Serve area o ripetibilita' o scala per livello.
        "ammissione": ["*tre_di_D2D3D4D5D6"],
        "regola": "almeno due fra area (D2), ripetibilita' (D4), scala (D5); oppure critico (D3) o multiattacco (D6): il solo danno singolo e' la versione stretta",
    },
    "face": {
